SELECT start_clock, start_delay_sec, count(*), ec.name, ec.id, holding_status FROM entry_groups eg INNER JOIN entry_categories ec ON ec.entry_group_id=eg.id INNER JOIN races_categories rc ON rc.code=ec.races_category_code WHERE eg.meet_code=(SELECT eg2.meet_code FROM entry_categories e2 JOIN entry_groups eg2 ON eg2.id=e2.entry_group_id WHERE e2.id=24693) AND eg.deleted=0 AND ec.deleted=0 GROUP BY ec.id ORDER BY rc.display_rank, ec.name;
